const PB_BOOKREF={1:'Розенталь, «Орфография и пунктуация», § 11–12; «Упражнения и комментарии», § 28 (прописные в начале предложения — упр. 176–186 по теме); Адамчик, «Употребление прописных букв»',2:'Розенталь, «Упражнения и комментарии», § 28, упр. 176, 184; «Русский язык» (пособие), упр. 61–62, 64; Сборник правил и упражнений, § 16',3:'Розенталь, «Упражнения и комментарии», § 28, упр. 177, 184–185; «Русский язык» (пособие), упр. 62–63',4:'Розенталь, «Упражнения и комментарии», § 28, упр. 178–181; «Русский язык» (пособие), упр. 61, 65',5:'Розенталь, «Упражнения и комментарии», § 28, упр. 182–183; «Русский язык» (пособие), упр. 61',6:'Розенталь, «Орфография и пунктуация», § 26, § 109, § 111; «Упражнения и комментарии», § 28, упр. 184–186',7:'Розенталь, «Упражнения и комментарии», § 28, упр. 184–186; «Русский язык» (пособие), упр. 63–65'};
